# Helper envs/tasks/deliver_to_human.py / DeliverToHuman._object_bottom_z
def _object_bottom_z(self) -> float:
        md_path = (
            ASSETS_PATH / "objects" / self.obj_name
            / f"model_data{self.obj_model_id}.json"
        )
        with open(md_path) as f:
            md = json.load(f)
        extents = np.asarray(md["extents"], dtype=np.float64)
        scale = np.asarray(md.get("scale", [1.0, 1.0, 1.0]), dtype=np.float64)
        if scale.size == 1:
            scale = np.repeat(scale, 3)
        center = np.asarray(md.get("center", [0.0, 0.0, 0.0]), dtype=np.float64)
        half = 0.5 * extents * scale
        center = center * scale
        corners = np.array([
            center + np.array([sx * half[0], sy * half[1], sz * half[2]])
            for sx in (-1.0, 1.0)
            for sy in (-1.0, 1.0)
            for sz in (-1.0, 1.0)
        ])
        pose = self.obj_actor.get_pose()
        R = t3d.quaternions.quat2mat(np.asarray(pose.q, dtype=np.float64))
        world = np.asarray(pose.p, dtype=np.float64) + corners @ R.T
        return float(np.min(world[:, 2]))

# Helper envs/tasks/deliver_to_human.py / DeliverToHuman._object_table_clearance
def _object_table_clearance(self) -> float:
        return self._object_bottom_z() - float(self.TABLE_TOP_Z)

# Helper envs/base_task.py / BaseTask.safe_distance_summary
def safe_distance_summary(self) -> dict:
        """Episode-level closest robot-avatar signed distance.

        Positive values are clearance, zero is contact, and negative values
        are penetration depth.  Distances use the same sampled robot collision
        geometry and avatar capsule / palm-box model as avatar_collision.
        """
        if self.avatar_collision_checker is None:
            return {"enabled": False}

        def _distance_or_inf(record: dict) -> float:
            try:
                d = float(record.get("min_distance", float("inf")))
            except (TypeError, ValueError):
                return float("inf")
            return d if np.isfinite(d) else float("inf")

        n_checks = len(self.avatar_collision_log)
        log = [
            r for r in self.avatar_collision_log
            if np.isfinite(_distance_or_inf(r))
        ]
        if not log:
            return {
                "enabled": True,
                "n_checks": n_checks,
                "n_valid_distance_checks": 0,
                "safe_distance_m": None,
                "closest_pair": None,
                "closest_frame": None,
            }
        best = min(log, key=_distance_or_inf)
        return {
            "enabled": True,
            "n_checks": n_checks,
            "n_valid_distance_checks": len(log),
            "safe_distance_m": _distance_or_inf(best),
            "closest_pair": best.get("closest_pair"),
            "closest_frame": best.get("frame"),
        }

