# Helper envs/task_bases/place_bread_in_basket.py / PlaceBreadInBasket._basket_top_z
def _basket_top_z(self) -> float:
        """Live basket rim height (static basket AABB top); the pre-build
        estimate, then table + nominal basket depth, as fallbacks."""
        try:
            aabb = np.asarray(to_numpy(self.basket.entity.get_AABB()), dtype=float)
            if aabb.shape == (2, 3) and np.all(np.isfinite(aabb)):
                return float(aabb[1, 2])
        except Exception:
            pass
        rim = getattr(self, "_basket_rim_z", None)
        if rim is not None:
            return float(rim)
        return float(self.TABLE_TOP_Z) + self.NOMINAL_BASKET_DEPTH_M

# Helper envs/task_bases/place_bread_in_basket.py / PlaceBreadInBasket._bread_resting_in_basket
def _bread_resting_in_basket(self, bread, basket_xy=None, rim_z=None) -> bool:
        """Success predicate for one loaf: inside the basket footprint and
        above the table, resting (lowest point at most
        ``SUCCESS_REST_MAX_ABOVE_RIM_M`` above the basket rim, which still
        admits a loaf stacked on the other), and held by neither the avatar
        nor the gripper."""
        if basket_xy is None:
            basket_xy = to_numpy(self.basket.entity.get_pos()).ravel()[:2]
        p = to_numpy(bread.entity.get_pos()).ravel()[:3]
        dxy = float(np.linalg.norm(p[:2] - basket_xy))
        above_table = p[2] > self.TABLE_TOP_Z - self.SUCCESS_TABLE_Z_MARGIN
        if not (dxy <= self.SUCCESS_DIST_XY_M and above_table):
            return False
        if rim_z is None:
            rim_z = self._basket_top_z()
        if entity_bottom_z(bread, p[2]) > rim_z + self.SUCCESS_REST_MAX_ABOVE_RIM_M:
            return False
        return not held_by_anyone(self, bread, self._bread_bbox_center(bread, p))

