# Helper envs/task_bases/place_bread_in_basket.py / PlaceBreadInBasket._basket_top_z
def _basket_top_z(self) -> float:
        """Live basket rim height (static basket AABB top); the pre-build
        estimate, then table + nominal basket depth, as fallbacks."""
        try:
            aabb = np.asarray(to_numpy(self.basket.entity.get_AABB()), dtype=float)
            if aabb.shape == (2, 3) and np.all(np.isfinite(aabb)):
                return float(aabb[1, 2])
        except Exception:
            pass
        rim = getattr(self, "_basket_rim_z", None)
        if rim is not None:
            return float(rim)
        return float(self.TABLE_TOP_Z) + self.NOMINAL_BASKET_DEPTH_M

# Helper envs/task_bases/place_bread_in_basket.py / PlaceBreadInBasket._bread_resting_in_basket
def _bread_resting_in_basket(self, bread, basket_xy=None, rim_z=None) -> bool:
        """Success predicate for one loaf: inside the basket footprint and
        above the table, resting (lowest point at most
        ``SUCCESS_REST_MAX_ABOVE_RIM_M`` above the basket rim, which still
        admits a loaf stacked on the other), and held by neither the avatar
        nor the gripper."""
        if basket_xy is None:
            basket_xy = to_numpy(self.basket.entity.get_pos()).ravel()[:2]
        p = to_numpy(bread.entity.get_pos()).ravel()[:3]
        dxy = float(np.linalg.norm(p[:2] - basket_xy))
        above_table = p[2] > self.TABLE_TOP_Z - self.SUCCESS_TABLE_Z_MARGIN
        if not (dxy <= self.SUCCESS_DIST_XY_M and above_table):
            return False
        if rim_z is None:
            rim_z = self._basket_top_z()
        if entity_bottom_z(bread, p[2]) > rim_z + self.SUCCESS_REST_MAX_ABOVE_RIM_M:
            return False
        return not held_by_anyone(self, bread, self._bread_bbox_center(bread, p))

# Helper envs/base_task.py / BaseTask._compute_target_metrics
def _compute_target_metrics(self) -> Optional[dict]:
        """Resolve the spec into a raw-metrics dict, or None if unavailable.

        Keys: object_pos, target_pos, dist_xy, dist_3d, dz, and (if the spec
        supplies ``object_axis_fn``) tilt_deg = angle(axis, world +Z).
        """
        spec = self.target
        if spec.object is None or spec.position is None:
            return None

        if callable(spec.object_pos_fn):
            try:
                obj_pos = np.asarray(spec.object_pos_fn(),
                                     dtype=float).ravel()[:3]
            except Exception:
                return None
        else:
            entity = getattr(spec.object, "entity", spec.object)
            try:
                obj_pos = np.asarray(to_numpy(entity.get_pos()),
                                     dtype=float).ravel()[:3]
            except Exception:
                return None

        try:
            tgt_raw = spec.position() if callable(spec.position) else spec.position
            tgt_pos = np.asarray(tgt_raw, dtype=float).ravel()[:3]
        except Exception:
            return None

        metrics = {
            "object_pos": obj_pos,
            "target_pos": tgt_pos,
            "dist_xy": float(np.linalg.norm(obj_pos[:2] - tgt_pos[:2])),
            "dist_3d": float(np.linalg.norm(obj_pos - tgt_pos)),
            "dz": float(obj_pos[2] - tgt_pos[2]),
        }

        if callable(spec.object_axis_fn):
            try:
                axis = np.asarray(spec.object_axis_fn(),
                                  dtype=float).ravel()[:3]
                n = float(np.linalg.norm(axis))
                if n > 1e-8:
                    axis = axis / n
                    metrics["tilt_deg"] = float(np.degrees(
                        np.arccos(np.clip(axis[2], -1.0, 1.0))))
            except Exception:
                pass

        return metrics

