        metrics = super().evaluate()
        if self.config.get("dump_neutral_initial_clearance_v1") is True:
            metrics["dump_neutral_initial_clearance"] = dict(
                self._dump_neutral_initial_clearance_counts
            )
        return metrics

# envs/task_bases/neutral_avatar_table_work.py / NeutralAvatarTableWorkMixin.check_success
def check_success(self) -> bool:
        parent_ok = self.neutral_parent_success()
        no_avatar_collision = self.neutral_avatar_success_gate()
        self._neutral_debug(
            f"[neutral_avatar] parent_ok={parent_ok}, "
            f"no_avatar_collision={no_avatar_collision}"
        )
        return bool(parent_ok and no_avatar_collision)

# envs/task_bases/neutral_avatar_table_work.py / NeutralAvatarTableWorkMixin.evaluate
def evaluate(self) -> dict:
        metrics = super().evaluate()
        metrics.update(self.interaction_controller.interaction_metrics(self))
        # Contested-layout flag + chosen anchor, so results split.
        metrics.update(self.neutral_layout_metrics())
        metrics.update(self.neutral_aware_metrics())
        return metrics

# envs/task_bases/dump_bin.py / DumpBin.check_success
def check_success(self) -> bool:
        big_x, big_y = self.big_bin_pose.p[:2]
        rim_z = self._big_bin_rim_z
        x_half, y_half = self._big_bin_xy_half

        in_count = 0
        for i, cube in enumerate(self.objects):
            p = self._dump_object_center(cube)
            in_xy   = abs(p[0] - big_x) < x_half and abs(p[1] - big_y) < y_half
            below_r = p[2] < rim_z + self.SUCCESS_RIM_MARGIN
            above_f = p[2] > self.SUCCESS_FLOOR_Z_MIN
            inside  = in_xy and below_r and above_f
            if inside:
                in_count += 1

        threshold = max(1, (self.num_objects + 1) // 2)
        # plan_success can flip False on internal mplib retry fallbacks even
        # when the visible motion succeeds, so final cube positions are the
        # authoritative success signal.
        return in_count >= threshold

# envs/task_bases/dump_bin.py / DumpBin.evaluate
def evaluate(self) -> dict:
        out = super().evaluate()
        check = getattr(self, "_final_gripper_pose_check", None)
        if check is not None:
            xy_ok = bool(check["xy_err"] <= check["xy_threshold"])
            pose_ok = bool(xy_ok and check["z_ok"])
            out["final_gripper_pose"] = {**check, "xy_ok": xy_ok, "success": pose_ok}
            if not pose_ok:
                out["success"] = False
        return out

