        self.joint_name = joint_name
        self.angle_th = angle_th
        self.condition_has_been_met = False
        self.kwargs = kwargs

    def is_met(self, physics=None):
        if self.condition_has_been_met:  # once met, always met
            return True
        if self.joint_name is None:
